import { type Token } from "./song.ts";
import { type Pitch } from "./pitch.ts";
/** 几条 track（第一条 = 主人）→ 一条：
 *  · 切点 = 任何人的音开始 / 结束的地方 + 主人的记号所在的地方；每一段 = 那一刻正在响的所有音并成一个和弦（从高到低、同音只留一个），没人响 = 休止；
 *  · 这一段没有新起的音（只是别人那边结束了 / 记号切开的）= 连着上一段（tie）；有新起的音时还在响的长音照样画进和弦（单声部写法表达不了「只连其中一个音」）；
 *  · 主人的记号（力度 / 渐强渐弱 / 小节线 / 反复 / 风格 / 速度 / 调号 / 拍号…）按原来的位置留着（原 token，id 不变）；谱号 / 八度线不要（这一行自己挑）；
 *  · 歌词 = 主人在这一刻起的那个音的；
 *  · keyOf：把某一位的音换成别的音高（一家全是鼓：固定敲一件的 = 那一件的鼓键，好画在五线鼓谱上它那一线）；
 *  · pick：只要第几位、从哪一刻起的那些音（双手谱上 / 下那张、声部 1 / 2 各并一条——见 planHands）；marks = "bars"：只留小节线 / 调号 / 拍号（力度、歌词归最上面那条）。
 *  · hits（一家全是鼓，v0.16.54）：一个鼓音只在它敲下去那一刻出现——有人新敲的那一段只画新敲的（还「响着」的长音不再并进来）；
 *    没人新敲、只剩长音在响的那一截：和上一段完全是同一批音 = 连着（被记号切开的），不是 = 休止。user 11-09「kick drum是一个长音，每小节一下，但是现在显示成三个音了」
 *    （附点四分的底鼓叠着邦哥的八分 = 三个和弦里都有它；鼓不画连音线，看着就是敲了三下）。
 *  新造的音 / 休止 id 是负数（不和真 token 撞）。 */
export interface MergeOpts {
    keyOf?: (member: number, p: Pitch) => Pitch;
    pick?: (member: number, t0: number) => boolean;
    marks?: "all" | "bars";
    hits?: boolean;
}
/** 合租叠起来怎么分手 / 分声部（v0.10.31；user「我现在觉得合租的时候还是智能分左右手和声部的对应关系比较好」「以及你也可以选择合租的时候不用双手谱」
 *  「双手谱线的分工能不能更智能一点，比如如果月读几乎都是高音谱号，另外一个几乎都是低音谱号，那么几个outlier不要乱认领。你觉得小节的粒度算？」「piano3…确实会高低声部乱跑」）：
 *  · 每位一张「家」谱：这张纸上它所有音的中位数在中央 C 以上 = 上谱，以下 = 下谱。大家都在同一边、或者一张谱读得下（clef.ts wantsGrand）= 一张谱，不用双手谱；
 *  · 双手谱时按**小节**换：这一小节它的音明显在另一边（中位数离中央 C 超过一个四度）才换过去，几个出格的音不换（乱跑的那位一小节一小节跟着走）；
 *  · 同一张谱上同一小节有两位以上 = 按各人的中位数在最大的空当处分两组：上面那组 = 声部 1（符干朝上）、下面那组 = 声部 2（符干朝下）；同组的并成和弦。
 *  pick(谱 0 上 / 1 下, 声部 1 / 2) = 给 mergeTracks 的 pick。 */
export interface HandPlan {
    grand: boolean;
    pick: (staff: 0 | 1, voice: 1 | 2) => (member: number, t0: number) => boolean;
}
/** homes（可选）：各位的家谱 = 它拆开来时的谱号（低音谱号 = 下谱、高音谱号 = 上谱；null = 它自己是大谱表 / 不知道 → 按音高中位数）。v0.10.38；user「所以合租的时候分谱号你用的是分轨的时候的谱号分配对吧，聪明！」——
 *  原来只按中位数，这一版照这个思路改成先看各位自己的谱号（和拆开来看的一致，手动设过的谱号也算数）。 */
/** force（v0.10.42）：主人自己设成大谱表 = 这一行一定是双手谱（user「就是我希望让合租是grand staff调piano1没用需要调2，很奇怪」——原来只看各位的家谱分不分两边，
 *  主人设大谱表不算数；房客里谁设成大谱表才会按音高掉到下谱）。各位的谱号都在同一边时 = 按音高中位数在最大的空当处分上下（上面那组 = 上谱）。 */
export declare function planHands(tracks: Token[][], wantsGrand: (merged: Token[]) => boolean, homes?: readonly (0 | 1 | null)[], force?: boolean): HandPlan;
export declare function mergeTracks(tracks: Token[][], opt?: MergeOpts): Token[];
